using System.Collections.Generic;using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using UnityEngine;using Rootborn.Game.Minigames;
namespace Rootborn.Tests.EditMode.Minigames{
public sealed class MinigamePropAssetTests{
const string Root="Assets/Art/CareerMinigames/Comfy31Props/";
[TestCase("puzzle_workbench",96,48)][TestCase("puzzle_drawer_cabinet",48,96)][TestCase("puzzle_desk",96,64)][TestCase("puzzle_chair",48,48)][TestCase("training_target",48,48)][TestCase("traffic_cone",48,48)][TestCase("road_barrier",96,48)]
public void PropSprites_HaveSavedPixelSettingsAndAddress(string name,int width,int height){string path=Root+name+".png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null,name);Assert.That(s.rect.size,Is.EqualTo(new Vector2(width,height)));Assert.That(s.pivot,Is.EqualTo(new Vector2(width/2f,height/2f)));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));var e=AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(e,Is.Not.Null);Assert.That(e.address,Is.EqualTo("sprites/minigame/"+name.Replace('_','-')));Assert.That(e.labels,Does.Contain("CareerMinigames"));}
[Test]public void PlacementChallenges_UseSpritesMatchingDeclaredPieceSizes(){var map=new Dictionary<Vector2Int,string>{{new Vector2Int(2,1),"puzzle_desk"},{new Vector2Int(3,1),"puzzle_workbench"},{new Vector2Int(1,2),"puzzle_drawer_cabinet"},{Vector2Int.one,"puzzle_chair"}};foreach(string name in new[]{"Interior1","Interior2","Interior3","WorkshopIntro"}){var d=AssetDatabase.LoadAssetAtPath<PlacementChallengeDefinition>("Assets/Data/StudentLife/Minigames/Challenges/"+name+".asset");var so=new SerializedObject(d);var sizes=so.FindProperty("_pieceSizes");var sprites=so.FindProperty("_symbolSprites");Assert.That(sprites.arraySize,Is.EqualTo(sizes.arraySize),name);for(int j=0;j<sizes.arraySize;j++)Assert.That(sprites.GetArrayElementAtIndex(j).objectReferenceValue,Is.SameAs(AssetDatabase.LoadAssetAtPath<Sprite>(Root+map[sizes.GetArrayElementAtIndex(j).vector2IntValue]+".png")),name+" piece "+j);Assert.That(d.IsValid,Is.True);}}
[Test]public void TargetAndTravelChallenges_KeepExplicitTargetObstacleRoles(){foreach(string name in new[]{"Training1","Training2","Training3","Travel2","Travel3"}){var d=AssetDatabase.LoadAssetAtPath<TargetDodgeChallengeDefinition>("Assets/Data/StudentLife/Minigames/Challenges/"+name+".asset");var sprites=new SerializedObject(d).FindProperty("_symbolSprites");Assert.That(sprites.arraySize,Is.EqualTo(2),name);bool travel=name.StartsWith("Travel");Assert.That(sprites.GetArrayElementAtIndex(0).objectReferenceValue,Is.SameAs(travel?null:AssetDatabase.LoadAssetAtPath<Sprite>(Root+"training_target.png")),name);Assert.That(sprites.GetArrayElementAtIndex(1).objectReferenceValue,Is.SameAs(AssetDatabase.LoadAssetAtPath<Sprite>(Root+(travel?"road_barrier":"traffic_cone")+".png")),name);Assert.That(d.IsValid,Is.True);}}
}}
